// Defensive server-side CORS middleware: allowlist, never blind reflection.
const ALLOWED = new Set([
  "https://app.example.com",
  "https://staging.example.com"
])

function cors(req, res, next) {
  const origin = req.headers.origin

  if (origin && ALLOWED.has(origin)) {
    // Credentialed endpoints must name ONE exact origin.
    res.setHeader("Access-Control-Allow-Origin", origin)
    res.setHeader("Access-Control-Allow-Credentials", "true")
    res.setHeader("Vary", "Origin") // cache safety: response differs per origin
  }
  // No origin, or unknown origin: send NO CORS headers.
  // The browser will block the read — exactly what we want.

  if (req.method === "OPTIONS") {
    res.setHeader("Access-Control-Allow-Methods", "GET, POST")
    res.setHeader("Access-Control-Allow-Headers", "Content-Type")
    return res.status(204).end()
  }
  next()
}

// The test that proves the defense:
// fetch("https://api.example.com/me", { credentials: "include" })
//   from https://evil.example  ->  response unreadable (no ACAO header)
